const roomArt={bedroom:()=>itemSvg('bed'),kitchen:()=>'<svg viewBox="0 0 100 100" aria-hidden="true"><path d="M15 40H85V85H15ZM15 53H85M52 53V85M19 25H81V40H19Z" fill="none" stroke="currentColor" stroke-width="4"/><circle cx="34" cy="32" r="5" fill="currentColor"/><circle cx="65" cy="32" r="5" fill="currentColor"/></svg>',bathroom:()=>'<svg viewBox="0 0 100 100" aria-hidden="true"><path d="M14 48H86Q82 78 66 78H32Q18 78 14 48ZM23 48V24Q23 12 40 20M30 78L26 89M70 78L74 89" fill="none" stroke="currentColor" stroke-width="5"/></svg>', 'living room':()=>itemSvg('sofa')};
export const mechanicStyles=`.classroom-stage{position:relative;width:100%;aspect-ratio:16/9;min-height:260px;border-radius:16px;overflow:hidden}.classroom-stage>img{position:absolute;inset:0;width:100%!important;max-width:none!important;height:100%!important;object-fit:fill}.interactive-book{position:absolute;left:26%;top:57%;width:48%;height:29%;display:flex;transform:perspective(400px) rotateX(25deg);filter:drop-shadow(0 8px 4px #0007)}.interactive-book span{width:50%;height:100%;border:3px solid #b08c4d;background:repeating-linear-gradient(#f7e8bd 0 10px,#d5bf8d 11px 12px);border-radius:3px 14px 14px 3px}.interactive-book span:first-child{transform:rotate(-4deg);border-radius:14px 3px 3px 14px}.interactive-book.closed{width:55%;height:34%;left:23%;top:54%}.interactive-book.closed span:first-child{display:none}.interactive-book.closed span:last-child{width:100%;background:#23677b;border:5px solid #ddb96f;border-radius:5px;box-shadow:inset 0 0 0 7px #184656}.book-controls{display:flex;justify-content:center;flex-wrap:wrap;gap:12px;margin-top:18px}.book-controls [aria-pressed=true]{outline:3px solid #ecc779}.furniture-world{position:relative;aspect-ratio:1429/804;width:100%;min-height:330px;border-radius:16px;overflow:hidden}.furniture-world>img{position:absolute;width:100%;height:100%;object-fit:fill;inset:0}.furniture-target{position:absolute;width:28%;height:43%;border:2px solid transparent;border-radius:18px;background:transparent;display:flex;align-items:end;justify-content:center;padding:5px;cursor:pointer}.furniture-target:hover,.furniture-target:focus-visible{border:3px solid #ffe1a2;background:#ffe1a222;outline:none}.furniture-target span{font:700 13px Arial;color:#fff7d9;background:#163540e8;border:1px solid #edc77d88;border-radius:20px;padding:6px 10px}.furniture-bed{left:4%;top:3%}.furniture-chair{left:37%;top:3%}.furniture-table{left:69%;top:3%}.furniture-sofa{left:4%;top:53%}.furniture-door{left:37%;top:53%}.furniture-window{left:69%;top:53%}.packing-stage{position:relative;aspect-ratio:16/9;overflow:hidden;border-radius:15px;width:100%;min-height:220px}.packing-stage>img{width:100%!important;max-width:none!important;height:100%!important;position:absolute;inset:0;object-fit:cover}.packed-items{position:absolute;top:20%;left:33%;width:33%;height:37%;display:flex;justify-content:center;align-items:center;gap:7px}.packed-items span{width:42%;max-width:80px;background:#f1d39c;border-radius:9px;padding:4px;color:#233d45;transform:rotate(-8deg)}.packed-items svg{width:100%;display:block}.packing-stage~.discovery-grid{margin-top:8px;grid-template-columns:repeat(2,minmax(0,1fr));width:100%}.packing-stage~.discovery-grid .discovery-item{min-height:105px}.packing-stage~.discovery-grid svg{width:58px;height:58px}.packing-stage{isolation:isolate}.packed-items{z-index:1}.classroom-stage{isolation:isolate}.interactive-book{z-index:1}.room-dollhouse{position:relative;aspect-ratio:1429/804;width:100%;min-height:300px;overflow:hidden;border-radius:16px}.room-dollhouse>img{position:absolute;width:100%;height:100%;object-fit:fill;inset:0}.room-hotspot{position:absolute;width:42%;height:39%;border:2px solid transparent;border-radius:16px;background:transparent;color:#fff8df;display:flex;align-items:end;justify-content:center;padding:7px;cursor:pointer}.room-hotspot span{background:#183d46e8;padding:6px 12px;border:1px solid #edc77d88;border-radius:20px;font:700 14px Arial}.room-hotspot:hover,.room-hotspot:focus-visible{border:3px solid #ffe1a2;background:#ffe1a221;outline:none}.room-bedroom{left:4%;top:5%}.room-bathroom{left:55%;top:5%}.room-kitchen{left:4%;top:54%}.room-living-room{left:55%;top:54%}@media(max-width:500px){.room-dollhouse{aspect-ratio:1/1;min-height:330px}.room-hotspot span{font-size:12px;padding:5px 8px}}.discovery-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.discovery-grid.rooms{grid-template-columns:repeat(2,minmax(0,1fr))}.discovery-item{min-width:0;min-height:116px;display:grid;place-items:center;gap:8px;padding:12px;border:2px solid #577180;border-radius:16px;background:#19384b;color:#f5dfad;font:700 16px Arial;cursor:pointer}.discovery-item svg{width:70px;height:70px}.discovery-item.selected{border-color:#f1bf65;background:#345468}.discovery-item:focus-visible,.position-zone:focus-visible{outline:4px solid #8be1da;outline-offset:3px}.packing-bag{width:110px;margin:20px auto;color:#edc27a}.packing-bag svg{width:100%}.pack-submit{display:block;margin:18px auto 0;padding:14px 24px;background:#edc27a;color:#11192f;border:0;border-radius:12px;font:bold 17px Arial}.pack-submit:disabled{opacity:.45}.position-scene{position:relative;height:345px;border-radius:16px;background:#13273b}.reference-box{position:absolute;top:118px;left:calc(50% - 86px);width:172px;height:114px;background:#a97438;border:6px solid #f1c578;border-radius:8px;pointer-events:none;box-shadow:inset 0 10px 0 #70491e}.reference-box:before{content:"";position:absolute;inset:13px 16px;background:#51391e;border-radius:7px}.reference-box:after{content:"";position:absolute;left:8px;right:8px;top:108px;height:74px;border-left:12px solid #a97438;border-right:12px solid #a97438}.position-instruction{text-align:center;color:#e9c887}.position-zone.selected{border-style:solid;border-color:#f1c578;background:#345468aa}.position-zone .position-empty{display:block;font-size:28px;line-height:40px;color:#b4d2e3}.position-loose-ball{position:absolute;left:20px;top:55px;display:grid;justify-items:center;gap:6px;color:#e9c887;font-size:13px}.position-zone{position:absolute;left:calc(50% - 60px);width:120px;height:66px;border:2px dashed #91c7e8;border-radius:12px;background:#253f5588;color:#e9c887;cursor:pointer}.position-zone.on{top:66px}.position-zone.in{top:141px}.position-zone.under{top:242px}.position-dot{display:inline-block;width:38px;height:38px;border-radius:50%;background:#e9b251;border:3px solid #fff0be;box-shadow:inset -7px -7px 0 #bd762b}.position-label{font:700 13px Arial}.position-zone .position-label{display:block}.position-zone:not(.selected) .position-dot{opacity:.35}@media(max-width:360px){.discovery-grid{gap:8px}.discovery-item{padding:8px;font-size:14px}.discovery-item svg{width:58px;height:58px}}`;
export function renderDiscoveryTask(task,selection=[]){
 if(task.type==='scene'&&task.scene==='rooms')return `<div class="room-dollhouse"><img src="/api/english-adventure/assets/discovery-rooms.webp" alt="بيت مفتوح: غرفة نوم وحمام فوق، ومطبخ وغرفة معيشة تحت">${task.targets.map(x=>`<button class="room-hotspot room-${x.replace(' ','-')}" data-discovery-answer="${safe(x)}" aria-label="${safe(x)}"><span>${safe(x)}</span></button>`).join('')}</div>`;
 if(task.type==='scene'&&task.scene==='furniture')return `<div class="furniture-world"><img src="/api/english-adventure/assets/discovery-furniture.webp" alt="ورشة فيها سرير وكرسي وطاولة وأريكة وباب ونافذة">${task.targets.map(x=>`<button class="furniture-target furniture-${x}" data-discovery-answer="${safe(x)}" aria-label="${safe(x)}"><span>${safe(x)}</span></button>`).join('')}</div>`;
 if(task.type==='scene')return `<div class="discovery-grid ${task.scene==='rooms'?'rooms':''}">${task.targets.map(x=>`<button class="discovery-item" data-discovery-answer="${safe(x)}" aria-label="${safe(x)}">${task.scene==='rooms'?roomArt[x]?.()||itemSvg(x):itemSvg(x)}<span lang="en" dir="ltr">${safe(x)}</span></button>`).join('')}</div>`;
 if(task.type==='pack')return `<div class="packing-stage"><img src="/api/english-adventure/assets/discovery-school.webp" alt="حقيبة مفتوحة على مكتب المدرسة"><div class="packed-items">${selection.map(x=>`<span>${itemSvg(x)}</span>`).join('')}</div></div><p role="status" dir="ltr" style="text-align:center">${selection.length} / ${task.required}</p><div class="discovery-grid">${task.items.map(x=>`<button class="discovery-item ${selection.includes(x)?'selected':''}" data-pack="${safe(x)}" aria-pressed="${selection.includes(x)}">${itemSvg(x)}<span lang="en" dir="ltr">${safe(x)}</span></button>`).join('')}</div><button id="submit-pack" class="pack-submit" ${selection.length!==task.required?'disabled':''}>جهّز الحقيبة ←</button>`;
 if(task.type==='book')return `<div class="classroom-stage"><img src="/api/english-adventure/assets/discovery-classroom.webp" alt="فصل في بيت الشجرة وكتاب على المكتب"><div class="interactive-book ${selection[0]==='close'?'closed':''}" role="img" aria-label="${selection[0]==='close'?'كتاب مقفول':'كتاب مفتوح'}"><span></span><span></span></div></div><div class="book-controls">${task.options.map(x=>`<button class="secondary" data-place="${x}" aria-pressed="${selection[0]===x}">${x==='open'?'افتح الكتاب':'اقفل الكتاب'} <span lang="en">${x}</span></button>`).join('')}</div><button id="submit-place" class="pack-submit" ${selection.length?'':'disabled'}>أكّد اختيارك ←</button>`;
 if(task.type==='place')return `<p class="position-instruction">اختار المكان، وبعدين ثبّت الكرة. تقدر تغيّر اختيارك.</p><div class="position-scene"><div class="reference-box" role="img" aria-label="صندوق على أرجل"></div>${!selection.length?'<div class="position-loose-ball"><span class="position-dot"></span><span>الكرة</span></div>':''}${task.options.map(x=>`<button class="position-zone ${safe(x)} ${selection[0]===x?'selected':''}" data-place="${safe(x)}" aria-label="${safe(x)}" aria-pressed="${selection[0]===x}">${selection[0]===x?'<span class="position-dot" aria-hidden="true"></span>':'<span class="position-empty" aria-hidden="true">+</span>'}</button>`).join('')}</div><button id="submit-place" class="pack-submit" ${selection.length?'':'disabled'}>ثبّت الكرة ←</button>`;
 return null;
}
export function wireDiscoveryTask(root,task,selection,onSelect,onSubmit){root.querySelectorAll('[data-discovery-answer]').forEach(b=>b.onclick=()=>onSubmit(b.dataset.discoveryAnswer));root.querySelectorAll('[data-pack]').forEach(b=>b.onclick=()=>{const value=b.dataset.pack;onSelect(selection.includes(value)?selection.filter(x=>x!==value):selection.length<task.required?[...selection,value]:selection)});root.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>onSelect([b.dataset.place]));const place=root.querySelector('#submit-place');if(place)place.onclick=()=>onSubmit(selection[0]);const submit=root.querySelector('#submit-pack');if(submit)submit.onclick=()=>onSubmit([...selection].sort().join('|'));}

