// Original touch-first clock/timeline/letter mechanics. Used only in private QA until routed.
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const journeyStyles=`.routine-illustration{width:100px;height:95px;object-fit:contain;display:block;border-radius:10px;margin:0 auto 6px}.journey-clock{position:relative;width:270px;height:270px;max-width:90vw;border:12px solid #d6aa60;border-radius:50%;background:#f8e8bd;margin:12px auto;box-shadow:inset 0 0 0 6px #fff3d4,0 12px 20px #0004;color:#173747}.clock-number{position:absolute;transform:translate(-50%,-50%);font:bold 20px Arial;width:44px;height:44px;border:0;border-radius:50%;background:transparent;color:#183a43}.clock-number:hover,.clock-number[aria-pressed=true]{background:#e3bb70}.clock-hand{position:absolute;left:calc(50% - 4px);bottom:50%;width:8px;transform-origin:bottom;background:#224f5c;border-radius:8px;pointer-events:none}.clock-hand.minute{height:90px;background:#9a6a34;width:5px;left:calc(50% - 2.5px)}.clock-hand.hour{height:62px}.clock-center{position:absolute;left:calc(50% - 9px);top:calc(50% - 9px);width:18px;height:18px;background:#b0823c;border-radius:50%;pointer-events:none}.journey-submit{padding:14px 26px;background:#ecc57d;color:#15313f;border:1px solid #ffdda0;border-radius:12px;font:bold 18px Arial;margin:15px auto;display:block}.journey-submit:disabled{opacity:.45}.journey-options{display:flex;flex-wrap:wrap;gap:10px;justify-content:center;direction:ltr}.journey-options button,.timeline-strip button{min-width:64px;min-height:52px;padding:10px 15px;border:2px solid #91c1c9;background:#214956;border-radius:12px;color:#fff0cd;font:700 20px Arial}.timeline-strip{min-height:100px;display:flex;flex-wrap:wrap;gap:8px;align-items:center;justify-content:center;background:#102f3c;border:2px dashed #91c1c9;border-radius:16px;padding:16px;margin:16px 0;direction:ltr}.timeline-strip button small{font-size:12px;color:#eac577}.letter-totem{width:150px;height:170px;margin:15px auto;display:grid;place-items:center;font:900 115px Georgia;color:#ffdb8d;background:linear-gradient(125deg,#315f68,#16343f);border:6px solid #b88743;border-radius:28px;box-shadow:0 8px #102b32}.letter-slots{display:flex;gap:8px;justify-content:center;flex-wrap:wrap;direction:ltr;margin:18px 0}.letter-slots button{font:700 40px Georgia;width:52px;height:68px;color:#263e43;background:#f6e2af;border:3px solid #c5944c;border-radius:10px}.journey-options [aria-pressed=true],.letter-slots [aria-pressed=true]{outline:4px solid #f4c36c;background:#487b7b;color:#fff0cd}`;
const routineImages={'wash':'wash','play':'play','get up':'wake-up','eat breakfast':'have-breakfast','go to school':'go-to-school','go to bed':'go-to-bed'};
const routineImage=x=>routineImages[x]?`<img class="routine-illustration" src="/api/english-adventure/assets/illustrated/${routineImages[x]}.webp" alt="" aria-hidden="true">`:'';
export function renderJourneyTask(t,selected=[]){
